ThreadLink::ThreadLink(Socket socket, bool heartbeat, BeatTiming timing,
                       std::chrono::milliseconds poll_delay) {
    if (poll_delay < std::chrono::milliseconds(1) ||
        poll_delay > std::chrono::milliseconds(10))
        throw std::invalid_argument("poll delay must be 1..10ms");
    if (heartbeat && !timing.valid()) throw std::invalid_argument("heartbeat timing");
    worker_ = std::thread([this, owned = std::move(socket), heartbeat, timing, poll_delay]() mutable {
          const LinkReport result = run(owned, heartbeat, timing, poll_delay);

    // Cooperative polling: no hard latency guarantee from the OS scheduler.
    if (!activity) std::this_thread::sleep_for(poll_delay);
}

