inline std::optional<LatencySummary> summarize_latency(std::vector<double> samples) {
    if (samples.empty()) {
        return std::nullopt;
    }
    for (const double s : samples) {
        if (!std::isfinite(s) || s < 0.0) {
            return std::nullopt;
        }
    }

    // Private copy: sorting must not disturb the caller's sample order.
    std::sort(samples.begin(), samples.end());

// Incremental mean of sorted nonnegative values avoids overflowing a sum,
// including platforms where long double has the same range as double.
long double mean = 0.0L;
std::size_t seen = 0;
for (const double s : samples) {
    ++seen;
    mean += (static_cast<long double>(s) - mean) / static_cast<long double>(seen);
}

const std::size_t n = samples.size();  // n > 0 past this point.

// Nearest-rank quantiles computed as p*q + ceil(p*r / 100) with
// n = 100*q + r. Splitting n this way keeps every intermediate (p <= 99,
// r < 100, q <= n/100) small enough that no std::size_t product overflows.
const std::size_t q = n / 100;
const std::size_t r = n % 100;
const std::size_t r50 = 50 * q + (50 * r + 99) / 100;
const std::size_t r99 = 99 * q + (99 * r + 99) / 100;

struct ProcessUsage {
    double cpu_seconds = 0;
    std::optional<std::uint64_t> voluntary_switches;
    std::optional<std::uint64_t> involuntary_switches;
};

inline std::optional<ProcessUsage> process_usage() {
    ProcessUsage result;
#ifdef _WIN32
    FILETIME created{}, exited{}, kernel{}, user{};
    if (!GetProcessTimes(GetCurrentProcess(), &created, &exited, &kernel, &user))
        return std::nullopt;
    const auto seconds = [](FILETIME v) {
        const std::uint64_t ticks = (std::uint64_t(v.dwHighDateTime) << 32) |
                                    v.dwLowDateTime;
        return static_cast<double>(ticks) * 1e-7;
    };
    result.cpu_seconds = seconds(kernel) + seconds(user);
#else
    rusage usage{};
    if (getrusage(RUSAGE_SELF, &usage) != 0) return std::nullopt;
    result.cpu_seconds = static_cast<double>(usage.ru_utime.tv_sec) +
        usage.ru_utime.tv_usec * 1e-6 + static_cast<double>(usage.ru_stime.tv_sec) +
        usage.ru_stime.tv_usec * 1e-6;
#ifdef __linux__
    result.voluntary_switches = static_cast<std::uint64_t>(usage.ru_nvcsw);
    result.involuntary_switches = static_cast<std::uint64_t>(usage.ru_nivcsw);
#endif
#endif
    return result;
}

